def newton_raphson(x0, tolerance=1e-7, max_iterations=1000):
    x = x0
    for _ in range(max_iterations):
        fx = poly(xs, x)
        if abs(fx) < tolerance:
            return x
        dfx = poly(derivative(xs), x)
        if abs(dfx) < tolerance:
            break
        x_new = x - fx / dfx
        if abs(x_new - x) < tolerance:
            return x_new
        x = x_new
    return x

