print(magic_square_test([[2, 7, 6], [9, 5, 1], [4, 3, 8]]))  # Should return True
print(magic_square_test([[1, 1, 1], [1, 1, 1], [1, 1, 1]]))  # Should return True
print(magic_square_test([[1, 2], [3, 4]]))  # Should return False (not a magic square)

def max_occurrences(lst):
    # Create a dictionary to store frequency of each element
    freq_dict = {}

    # Count frequency of each element
    for item in lst:
        if item in freq_dict:
            freq_dict[item] += 1
        else:
            freq_dict[item] = 1

    # Find the item with maximum frequency
    max_freq_item = None
    max_frequency = 0

    for item, frequency in freq_dict.items():
        if frequency > max_frequency:
            max_frequency = frequency
            max_freq_item = item

    return max_freq_item

