# Alternative solution using json module
import json

def dict_depth_json(d):
    if not isinstance(d, dict) or not d:
        return 0

    json_str = json.dumps(d)
    depth = 0
    current_depth = 0

    for char in json_str:
        if char == '{':
            current_depth += 1
            depth = max(depth, current_depth)
        elif char == '}':
            current_depth -= 1

    return depth

