def divisible_by_digits(startnum, endnum):
    result = []
    for num in range(startnum, endnum + 1):
        str_num = str(num)
        # Check if the number contains '0' (which makes it invalid)
        if '0' not in str_num:
            # Check if the number is divisible by each of its digits
            divisible = True
            for digit_char in str_num:
                digit = int(digit_char)
                if num % digit != 0:
                    divisible = False
                    break
            if divisible:
                result.append(num)
    return result

