def max_aggregate(lst):
    # Create a dictionary to store the aggregate scores
    aggregate = {}

    # Iterate through the list of tuples
    for name, score in lst:
        if name in aggregate:
            aggregate[name] += score
        else:
            aggregate[name] = score

